import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Stream from 'flarum/common/utils/Stream';
import LookControls, { Segmented } from '../../common/components/LookControls';
import { CURATED, decode, effective, encode, openKeys, payload } from '../../common/look';
import { own, save, show } from '../own';
import { currentView, reloadIfNeeded } from '../listViews';
import { storage } from '../../common/safe';
const t = (key, params) => app.translator.trans(`ernestdefoe-skylight.forum.studio.${key}`, params);

/**
 * The member Studio. Every change shows on the page at once (the page itself
 * is the preview); Done keeps it, closing any other way puts the old look
 * back. Loaded on first open, so it costs nothing until then.
 */
export default class StudioModal extends Modal {
  done = false;
  code = Stream('');
  codeError = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.saved = own();
    this.draft = {
      ...this.saved
    };
    this.savedScheme = String(app.colorScheme || 'auto');
  }
  className() {
    return 'Skylight-studio Modal--small';
  }
  title() {
    return [m(Icon, {
      name: "fas fa-sliders-h",
      className: "Skylight-studioIcon"
    }), ' ', t('title')];
  }
  content() {
    const p = payload();
    const look = effective(this.draft, p);
    return m("div", {
      className: "Modal-body Skylight-studioBody"
    }, m("p", {
      className: "Skylight-studioLead"
    }, t('lead')), m(LookControls, {
      look: look,
      sections: p.sections,
      presets: p.presets,
      presetsReplace: p.presetsReplace,
      backgrounds: p.backgrounds,
      before: app.allowUserColorScheme && this.mode(),
      onchange: (key, value) => this.set({
        [key]: value
      })
    }), p.sections.includes('share') && this.share(look), m("div", {
      className: "Skylight-studioFoot"
    }, m(Button, {
      className: "Button",
      icon: "fas fa-random",
      onclick: () => this.shuffle()
    }, t('shuffle')), m(Button, {
      className: "Button",
      onclick: () => this.reset()
    }, t('reset')), m(Button, {
      className: "Button Button--primary",
      loading: this.loading,
      onclick: () => this.finish()
    }, t('done'))));
  }
  mode() {
    const scheme = String(app.colorScheme || 'auto').replace(/-hc$/, '');
    const options = [['light', [m(Icon, {
      name: "far fa-sun"
    }), ' ', t('mode.light')]], ['dark', [m(Icon, {
      name: "far fa-moon"
    }), ' ', t('mode.dark')]], ['auto', [m(Icon, {
      name: "fas fa-adjust"
    }), ' ', t('mode.auto')]]];
    return m("fieldset", {
      className: "Skylight-section Skylight-section--mode"
    }, m("legend", null, t('mode.label')), Segmented(t('mode.label'), scheme, options, v => app.setColorScheme(v)));
  }
  share(look) {
    return m("fieldset", {
      className: "Skylight-section Skylight-section--share"
    }, m("legend", null, t('share.label')), m("div", {
      className: "Skylight-share"
    }, m("code", null, encode(look)), m(Button, {
      className: "Button",
      icon: "far fa-copy",
      onclick: () => this.copy(encode(look))
    }, t('share.copy'))), m("div", {
      className: "Skylight-share"
    }, m("input", {
      className: "FormControl",
      placeholder: "SKY-\u2026",
      "aria-label": t('share.paste_label'),
      bidi: this.code,
      "aria-invalid": this.codeError ? 'true' : undefined
    }), m(Button, {
      className: "Button",
      onclick: () => this.apply()
    }, t('share.apply'))), this.codeError && m("p", {
      className: "Skylight-note Skylight-note--error"
    }, t('share.invalid')));
  }
  copy(code) {
    // Without clipboard access (an insecure origin, or the visitor said no) the code stays on screen to copy by hand.
    navigator.clipboard?.writeText(code).then(() => app.alerts.show({
      type: 'success'
    }, t('share.copied')), () => app.alerts.show({
      type: 'error'
    }, t('share.copy_failed')));
  }
  set(changes) {
    // Only what the member may change, so a locked section stays the forum's.
    const open = openKeys(payload().sections);
    for (const [k, v] of Object.entries(changes)) if (open.includes(k)) this.draft[k] = v;
    this.preview(this.draft);
  }

  /** Show a look on the page; the list reloads if Cards came or went. */
  preview(choices) {
    const before = currentView();
    show(choices);
    reloadIfNeeded(before);
  }
  shuffle() {
    const pick = CURATED[Math.floor(Math.random() * CURATED.length)];
    this.set(pick);
  }
  reset() {
    this.draft = {};
    this.preview(this.draft);
  }
  apply() {
    const look = decode(this.code());
    this.codeError = !look;
    if (look) {
      this.set(look);
      this.code('');
    }
  }
  async finish() {
    this.loading = true;
    try {
      await save(this.draft);
      if (app.session.user && String(app.colorScheme) !== this.savedScheme) {
        await app.session.user.savePreferences({
          colorScheme: app.colorScheme
        });
      } else if (!app.session.user) {
        // Where core keeps a guest's scheme.
        storage((local, session) => session.setItem('colorScheme', String(app.colorScheme)), undefined);
      }
      this.done = true;
      this.hide();
    } finally {
      this.loading = false;
      m.redraw();
    }
  }
  onremove(vnode) {
    super.onremove(vnode);
    if (!this.done) {
      this.preview(this.saved);
      app.setColorScheme(this.savedScheme);
    }
  }
}
flarum.reg.add('ernestdefoe-skylight', 'forum/components/StudioModal', StudioModal);